-- | VersionSummary
data VersionSummary = VersionSummary
  { versionSummaryName :: !(Text) -- ^ /Required/ "name"
  , versionSummaryUrl :: !(Text) -- ^ /Required/ /ReadOnly/ "url"
  } deriving (P.Show, P.Eq, P.Typeable)

-- | FromJSON VersionSummary
instance A.FromJSON VersionSummary where
  parseJSON = A.withObject "VersionSummary" $ \o ->
    VersionSummary
      <$> (o .:  "name")
      <*> (o .:  "url")

-- | ToJSON VersionSummary
instance A.ToJSON VersionSummary where
  toJSON VersionSummary {..} =
   _omitNulls
      [ "name" .= versionSummaryName
      , "url" .= versionSummaryUrl
      ]


-- | Construct a value of type 'VersionSummary' (by applying it's required fields, if any)
mkVersionSummary
  :: Text -- ^ 'versionSummaryName' 
  -> Text -- ^ 'versionSummaryUrl' 
  -> VersionSummary
mkVersionSummary versionSummaryName versionSummaryUrl =
  VersionSummary
  { versionSummaryName
  , versionSummaryUrl
  }




-- * Auth Methods

-- ** AuthBasicBasicAuth
data AuthBasicBasicAuth =
  AuthBasicBasicAuth B.ByteString B.ByteString -- ^ username password
  deriving (P.Eq, P.Show, P.Typeable)

instance AuthMethod AuthBasicBasicAuth where
  applyAuthMethod _ a@(AuthBasicBasicAuth user pw) req =
    P.pure $
    if (P.typeOf a `P.elem` rAuthTypes req)
      then req `setHeader` toHeader ("Authorization", T.decodeUtf8 cred)
           & L.over rAuthTypesL (P.filter (/= P.typeOf a))
      else req
    where cred = BC.append "Basic " (B64.encode $ BC.concat [ user, ":", pw ])

-- ** AuthApiKeyCookieAuth
data AuthApiKeyCookieAuth =
  AuthApiKeyCookieAuth Text -- ^ secret
  deriving (P.Eq, P.Show, P.Typeable)

instance AuthMethod AuthApiKeyCookieAuth where
  applyAuthMethod _ a@(AuthApiKeyCookieAuth secret) req =
    P.pure $
    if (P.typeOf a `P.elem` rAuthTypes req)
      then req `setQuery` toQuery ("sessionid", Just secret)
           & L.over rAuthTypesL (P.filter (/= P.typeOf a))
      else req


